const expectedToken = process.env.META_VERIFY_TOKEN;
if (!expectedToken) {
  throw new Error('META_VERIFY_TOKEN is not configured');
}

const request = $input.first().json;
const query = request.query ?? {};
const valid = query['hub.mode'] === 'subscribe'
  && typeof query['hub.verify_token'] === 'string'
  && query['hub.verify_token'] === expectedToken
  && typeof query['hub.challenge'] === 'string';

return [{
  json: {
    response_code: valid ? 200 : 403,
    response_body: valid ? query['hub.challenge'] : ''
  }
}];

const crypto = require('crypto');
const secret = process.env.META_APP_SECRET;
if (!secret) {
  throw new Error('META_APP_SECRET is not configured');
}

const item = $input.first();
const signatureHeader = item.json.headers?.['x-hub-signature-256'];
if (typeof signatureHeader !== 'string') {
  throw new Error('Missing X-Hub-Signature-256 header');
}

const signatureMatch = /^sha256=([a-f0-9]{64})$/i.exec(signatureHeader);
if (!signatureMatch) {
  throw new Error('Invalid X-Hub-Signature-256 format');
}

const encodedRawBody = item.binary?.data?.data;
if (typeof encodedRawBody !== 'string') {
  throw new Error('Raw webhook body is unavailable; enable Raw Body on the Webhook node');
}
const rawBody = Buffer.from(encodedRawBody, 'base64');
const expectedDigest = crypto.createHmac('sha256', secret).update(rawBody).digest();
const receivedDigest = Buffer.from(signatureMatch[1], 'hex');
if (expectedDigest.length !== receivedDigest.length
    || !crypto.timingSafeEqual(expectedDigest, receivedDigest)) {
  throw new Error('Webhook signature verification failed');
}

return [{ json: item.json }];

const output = [];
const payload = $input.first().json.body;

for (const entry of payload?.entry ?? []) {
  for (const change of entry?.changes ?? []) {
    if (change?.field !== 'messages') continue;
    const value = change.value ?? {};
    const phoneNumberId = value.metadata?.phone_number_id;
    if (typeof phoneNumberId !== 'string' || !phoneNumberId) continue;

    for (const message of value.messages ?? []) {
      const waId = message.from ?? value.contacts?.find((contact) => contact.wa_id)?.wa_id;
      if (typeof waId !== 'string' || !waId || typeof message.id !== 'string' || !message.id) continue;

      const contact = value.contacts?.find((candidate) => candidate.wa_id === waId);
      const type = typeof message.type === 'string' && message.type ? message.type : 'unknown';
      const text = type === 'text' && typeof message.text?.body === 'string'
        ? message.text.body
        : `[non-text message: ${type}]`;
      const timestamp = Number(message.timestamp);
      if (!Number.isFinite(timestamp)) continue;

      output.push({
        json: {
          phone_number_id: phoneNumberId,
          wa_id: waId,
          profile_name: contact?.profile?.name ?? null,
          wa_message_id: message.id,
          message_type: type,
          message_body: text,
          timestamp
        }
      });
    }
  }
}

return output;
